input.command:
Add-Type -AssemblyName System.IO.Compression.FileSystem
$xmind = "E:\project\清泉跨境系统（企业级）\技术会.xmind"
$zip = [System.IO.Compression.ZipFile]::OpenRead($xmind)
foreach ($name in @('content.json','content.xml','metadata.json','manifest.json')) {
  $e = $zip.Entries | Where-Object { $_.FullName -eq $name }
  if ($e) {
    Write-Host "===== $name ====="
    $sr = New-Object System.IO.StreamReader($e.Open())
    $text = $sr.ReadToEnd()
    $sr.Close()
    Write-Output $text
  }
}
$zip.Dispose()
